CREATE OR REPLACE PROCEDURE public.sp_update_material_product(IN p_id uuid, IN p_name character varying, IN p_description text, IN p_category character varying, IN p_image_url character varying, IN p_material_type character varying, IN p_safety_instructions text, IN p_age_min_months integer, IN p_age_max_months integer, IN p_usage_restrictions text, IN p_cleaning_instructions text, IN p_return_policy text, IN p_is_active boolean, IN p_updated_at timestamp with time zone)  LANGUAGE plpgsql AS $procedure$ BEGIN     UPDATE material_products SET         name = p_name,         description = p_description,         category = p_category,         image_url = p_image_url,         material_type = p_material_type,         safety_instructions = p_safety_instructions,         age_min_months = p_age_min_months,         age_max_months = p_age_max_months,         usage_restrictions = p_usage_restrictions,         cleaning_instructions = p_cleaning_instructions,         return_policy = p_return_policy,         is_active = p_is_active,         updated_at = p_updated_at     WHERE id = p_id; END; $procedure$ ;
